window.CLASS_LOADOUTS={"interceptor":{"subtitle":"Мобильный критический убийца · главный получатель AP","priority":"Crit Chance → Focus → +AP/Movement","slots":[["Меч / фальшионы","The Weeping Blade III","Высокий шанс крита, большой бонус критического урона и Force Strike на шанс крита.","Ogen's Edict III (фальшионы: высокие криты) / The Grey Blade II","The_Weeping_Blade"],["Броня","Kantu's Vambrace III","+1 AP каждый ход, скорость и Focus. Очень сильна для цепочек Ruthless Precision.","Judgement's Refuge III: скорость и иммунитет к опасным поверхностям","Kantu%27s_Vambrace"],["Аксессуары","Augurium Scrolls + Sanctic Shard","Scrolls повышают шанс melee-крита; Shard повышает срабатывание пассивных эффектов.","Liber Daemonicum для усиления критического урона","Augurium_Scrolls"]],"note":"Для Execute-билда вместо критического меча можно выбрать Endbringer II (алебарда: +Stun, дополнительные AP за Execute)."},"justicar":{"subtitle":"Передача AP и WP-экономика · устойчивый саппорт","priority":"Макс. WP → Honour the Chapter → броня","slots":[["Ближний бой","Endbringer II","Алебарда для оглушений и Execute: улучшения усиливают Stun и возврат AP.","Final Justice III — тяжёлый молот с сильной критической механикой","Endbringer"],["Дальнее оружие","Storm Bolter / Psycannon","Psycannon пригодится только после открытия навыка доступа; до этого не жертвуй AP-поддержкой ради стрельбы.","Titan's Roar III для AoE при доступной Psycannon","Titan%27s_Roar"],["Броня","Scholar's Devotion III","Большой запас WP и защита от Drained — позволяeт чаще использовать Honour the Chapter.","Power in Faith III — WP и Focus","Scholar%27s_Devotion"],["Аксессуар","Sacred Incense","Добавляет максимум WP: больше действий для союзников.","Сервочереп или защита по ситуации","Sacred_Incense"]],"note":"Лучший Юстикар часто вообще не бьёт: его задача — раздать AP Инцептору и прикрыть команду."},"purgator":{"subtitle":"Дальний точечный урон или специалист по гранатам","priority":"Psilencer / Astral Aim ИЛИ гранаты — не обе ветки сразу","slots":[["Psilencer","Titan's Vengeance III","Сильный прямой урон и криты; хорош для Astral Aim и приоритетных целей.","Victory's Testament III — дальность и критические бонусы; Empyrean's Thunder II — промежуточный вариант","Titan%27s_Vengeance"],["Альтернатива AoE","Titan's Roar III","Psycannon с усилением Psychic Onslaught: выгоден против групп.","Soulflage I — доступный ранний вариант","Titan%27s_Roar"],["Броня стрелка","Kantu's Vambrace III","+AP для дополнительного выстрела или перезарядки.","Judgement's Refuge III — мобильность","Kantu%27s_Vambrace"],["Броня гранатомётчика","Keeper of the Flame III","+урон, дальность, заряд гранат. Превращает бойца в специалиста по AoE.","Heart of the Flame II — хорошая ранняя альтернатива","Keeper_of_the_Flame"],["Аксессуары","Blessed Greaves / Extended Magazine","Шанс дальнего крита либо дополнительные патроны — в зависимости от оружия.","Autoloader Skull для экономии AP на перезарядке","Blessed_Greaves"]],"note":"У Пургатора два разных билда. Для Psilencer выбирай криты/дальность; для Grenadier — броню и навыки на гранаты."},"apothecary":{"subtitle":"Iron Arm / Warp Speed · поддержка, а не только лечение","priority":"Iron Arm → Warp Speed → биомантия на расстоянии","slots":[["Narthecium","Lifegiver II","Восстанавливает HP и после улучшения продлевает эффект биомантии на 1 ход — особенно полезно для Iron Arm.","Tauma's Salve I — ранняя версия с длительностью","Lifegiver"],["Броня","Prodigy's Mantle III","Увеличивает заряды и дальность сервочерепов; хороша для поддержки.","Prodigy's Arms II; при Terminator-специализации — Scholar's Devotion III","Prodigy%27s_Mantle"],["Аксессуар","Apothecarion Skull / Medicae Skull","Дистанционно раздаёт биомантию или лечит бойцов.","Extractor Skull, пока ещё важен сбор семян","Apothecarion_Servo_Skull"]],"note":"С Lifegiver и Iron Arm Апотекарий поддерживает Stun/Execute-отряд. Не сравнивай его эффективность только по нанесённому урону."},"librarian":{"subtitle":"Групповой телепорт · Psychic Shriek · управление WP","priority":"WP → Gate of Infinity → Shriek / Vortex","slots":[["Посох","Kai's Evoker III","После улучшений даёт высокий Focus — помогает с автоматическими эффектами, включая Aegis Reaction.","Lel's Bride II / Brother's Diligence I","Kai%27s_Evoker"],["Броня","Scholar's Devotion III","WP и иммунитет к Drained: удобно при частом телепорте и AoE.","Power in Faith III — Focus и WP","Scholar%27s_Devotion"],["Аксессуар","Sacred Incense","Дополнительный WP для Gate of Infinity и Psychic Shriek.","Sanctic Shard — если строишь билд вокруг автоматических эффектов","Sacred_Incense"]],"note":"Основная ценность — не сила посоха, а достаточный WP для телепортации и контроля."},"chaplain":{"subtitle":"Литании · команда критов или цепочки Execute","priority":"WP → Litany of Hate / Intonement → защита","slots":[["Crozius Arcanum","The Manifest Word III","Шанс наложить Vulnerable, Executioner: AP за Execute; идеально для добиваний с Litany of Hate.","Hammer of the Righteous III — альтернативный Crozius","The_Manifest_Word"],["Броня","Power in Faith III","Focus и WP для длительной поддержки команды.","Scholar's Devotion III для максимального WP","Power_in_Faith"],["Аксессуар","Sacred Incense","Увеличивает доступные WP.","Medicae Skull для оборонительного отряда","Sacred_Incense"]],"note":"Litany of Hate и The Manifest Word особенно хороши в Stun-команде; для пары Пургаторов лучше Intonement for Guidance."},"paladin":{"subtitle":"Удержание позиции · Storm Shield и тяжёлые атаки","priority":"Fury of the Ancients / WP / Defend Position","slots":[["Ближнее оружие","Final Justice III","Сильный молот для редких решающих melee-атак.","Endbringer II для Stun/Execute; Titan's Wrath III для автоатаки First Strike","Final_Justice"],["Оборонительное оружие","Titan's Shield III","Storm Shield для Defend Position и усиленной защиты: заменяет дальнобойный слот.","Другой Storm Shield с защитой или сопротивлением","Titan%27s_Shield"],["Броня","Venerable III","Значительная броня и сопротивление негативным статусам.","Scholar's Devotion III, если упор на Fury of the Ancients и WP","Venerable"]],"note":"Паладин с щитом не выполняет роль дальнего стрелка. Для AoE-билда с оружием дальнего боя выбирай его вместо щита."},"purifier":{"subtitle":"Incinerator и гранаты · массовая зачистка","priority":"Flames of Purity / Incinerator Discipline → гранаты","slots":[["Incinerator","Piety's Ashes III","Высокий урон, улучшение Flames of Purity; после улучшений может наносить Stun по площади.","Helscorcher I — ранняя версия той же специализации","Piety%27s_Ashes"],["Броня","Keeper of the Flame III","Гранаты: +урон, дальность и боезапас.","Heart of the Flame II — бюджетный вариант","Keeper_of_the_Flame"],["Аксессуары","Extended Magazine / Frag / Krak","Больше топлива для атаки; Frag — Knockback, Krak — Armour Break.","Psychotroke для Crazed по группе","Extended_Magazine"]],"note":"Сначала выбери специализацию: Incinerator для огневого AoE или Wargear Discipline для гранат. Не смешивай все ветки прокачки."},"crowe":{"subtitle":"Уникальный герой Castellan Champion DLC","priority":"Фиксированный билд — распределения навыков нет","slots":[["Меч","Black Blade of Antwyr","Уникальное оружие Кроу, заменить нельзя.","Альтернатив нет","Black_Blade_of_Antwyr"],["Броня и аксессуары","Фиксированная экипировка","Изменять снаряжение и прокачку обычным способом нельзя.","Используй как готового запасного бойца","Castellan_Garran_Crowe"]],"note":"Кроу не требует поиска предметов для билда и не может заменить специализированного Инцептора с предметами III уровня."}};
